#include "HarmonyPresets.h"

static void testProgressionPresets(const File& root){
    const auto kind=HarmonyPresetKind::progression;auto factories=factoryHarmonyPresets(kind);bool valid=factories.size()==6,roundtrip=true;for(const auto& preset:factories){valid&=validateHarmonyPreset(preset).wasOk();HarmonyPreset read;roundtrip&=harmonyPresetFromJson(harmonyPresetToJson(preset),read).wasOk()&&JSON::toString(harmonyPresetToJson(read),false,22)==JSON::toString(harmonyPresetToJson(preset),false,22);}expect(valid,"six progression factory starters have valid bounded musical settings");expect(roundtrip,"all progression factories roundtrip every setting exactly");
    auto file=root.getChildFile("progression-preset-core.json");file.deleteFile();auto chord=factoryHarmonyPresets(HarmonyPresetKind::chord).front();chord.id="old-chord";chord.name="Shared name";expect(saveHarmonyPresets(file,{chord}).wasOk()&&(int)JSON::parse(file)["schema"]==1,"chord-only catalogs keep the legacy harmony schema");
    auto p=factories[4];p.id="personal-progression";p.name=String::fromUTF8("Моя последовательность");p.guide.enabled=false;p.progression.degrees={2,5,1};p.progression.octave=2;p.progression.beat=37;p.progression.step=1.125;p.progression.gate=.625;p.progression.velocity=.617f;p.progression.sevenths=true;p.progression.voiceLeading=false;p.progression.skipExact=false;std::vector<HarmonyPreset> rows;
    expect(putHarmonyPreset(file,p,false,harmonyPresetToken(file)).wasOk()&&(int)JSON::parse(file)["schema"]==2,"adding a progression upgrades the mixed harmony catalog to schema two");expect(loadHarmonyPresets(file,rows).wasOk()&&rows.size()==2&&rows[0].id==chord.id&&rows[1].name==p.name,"mixed legacy chord and Unicode progression entries reload together");auto json=harmonyPresetToJson(p);expect(!json["settings"].hasProperty("beat")&&!json.hasProperty("notes")&&rows[1].progression.beat==0,"progression presets omit insertion beat and song notes");expect(JSON::toString(harmonyPresetToJson(rows[1]),false,22)==JSON::toString(json,false,22),"progression catalog retains key visibility degrees timing velocity and voicing exactly");std::vector<Note> a,b;auto original=p.progression;original.beat=2;auto recalled=rows[1].progression;recalled.beat=2;expect(buildProgression({},8,p.guide,original,a).wasOk()&&buildProgression({},8,rows[1].guide,recalled,b).wasOk()&&a==b,"reloaded progression generates identical notes at a different target beat");
    auto sentinel=chord;auto sentinelJson=JSON::toString(harmonyPresetToJson(sentinel));for(auto key:{"degrees","octave","step","gate","velocity","sevenths","voiceLeading","skipExact"}){auto bad=harmonyPresetToJson(p);bad["settings"].getDynamicObject()->removeProperty(key);expect(harmonyPresetFromJson(bad,sentinel).failed()&&JSON::toString(harmonyPresetToJson(sentinel))==sentinelJson,"missing progression setting rejects without replacing the destination");}
    for(auto value:{var(true),var("2"),var(2.5),var(0),var(8)}){auto bad=harmonyPresetToJson(p);bad["settings"]["degrees"].getArray()->set(0,value);expect(harmonyPresetFromJson(bad,sentinel).failed(),"progression degrees reject bool string fractional and out-of-range values");}
    for(auto key:{"sevenths","voiceLeading","skipExact"}){auto bad=harmonyPresetToJson(p);bad["settings"].getDynamicObject()->setProperty(key,1);expect(harmonyPresetFromJson(bad,sentinel).failed(),"progression flag requires an actual boolean");}
    for(auto key:{"step","gate","velocity"})for(auto value:{var(true),var("0.5"),var(-.5),var(std::nan(""))}){auto bad=harmonyPresetToJson(p);bad["settings"].getDynamicObject()->setProperty(key,value);expect(harmonyPresetFromJson(bad,sentinel).failed(),"progression musical numeric fields reject malformed values");}
    auto bad=p;bad.progression.degrees.clear();expect(validateHarmonyPreset(bad).failed(),"empty preset progression rejects");bad=p;bad.progression.degrees.assign(17,1);expect(validateHarmonyPreset(bad).failed(),"more than sixteen preset degrees reject");bad=p;bad.progression.step=32;expect(validateHarmonyPreset(bad).failed(),"progression beyond maximum supported pattern length rejects");bad=p;bad.guide.scale=11;expect(validateHarmonyPreset(bad).failed(),"progression requires a seven-note preset scale");bad=p;bad.progression.octave=7;bad.guide.root=11;bad.progression.degrees={7};expect(validateHarmonyPreset(bad).failed(),"preset tones beyond MIDI pitch range reject");bad=p;bad.progression.velocity=.01f;HarmonyPreset minimum;expect(harmonyPresetFromJson(harmonyPresetToJson(bad),minimum).wasOk()&&minimum.progression.velocity==.01f,"one-percent progression velocity roundtrips exactly");
    auto bytes=file.loadFileAsString(),token=harmonyPresetToken(file);auto duplicate=p;duplicate.id="duplicate-progression";duplicate.name=p.name.toUpperCase();expect(putHarmonyPreset(file,duplicate,false,token).failed()&&file.loadFileAsString()==bytes,"case-insensitive progression name collision retains original catalog");duplicate.name=chord.name;expect(putHarmonyPreset(file,duplicate,false,token).wasOk(),"progression names can match a separate harmony tool");expect(!putHarmonyPreset(file,p,true,token).wasOk()&&!removeHarmonyPreset(file,p.id,token).wasOk(),"stale progression update and delete cannot replace a newer library");p.name="Updated progression";p.progression.gate=.75;expect(putHarmonyPreset(file,p,true,harmonyPresetToken(file)).wasOk()&&loadHarmonyPresets(file,rows).wasOk()&&rows[1].id==p.id&&rows[1].progression.gate==.75,"progression update preserves identity and replaces complete settings");
    auto exchange=root.getChildFile("progression-exchange.pulseharmony");expect(saveHarmonyPresets(exchange,{p}).wasOk()&&loadHarmonyPresets(exchange,rows).wasOk()&&rows.size()==1&&rows[0].kind==kind,"single-preset exchange supports progression settings");auto envelope=JSON::parse(exchange);envelope.getDynamicObject()->setProperty("schema",1);exchange.replaceWithText(JSON::toString(envelope));expect(loadHarmonyPresets(exchange,rows).failed()&&rows.size()==1&&rows[0].id==p.id,"mislabeled legacy progression file rejects atomically");envelope.getDynamicObject()->setProperty("schema",3);exchange.replaceWithText(JSON::toString(envelope));expect(loadHarmonyPresets(exchange,rows).failed(),"future harmony schema rejects");expect(removeHarmonyPreset(file,p.id,harmonyPresetToken(file)).wasOk()&&removeHarmonyPreset(file,duplicate.id,harmonyPresetToken(file)).wasOk()&&(int)JSON::parse(file)["schema"]==1&&loadHarmonyPresets(file,rows).wasOk()&&rows.size()==1&&rows[0].id==chord.id,"removing all progression entries restores a legacy-readable chord catalog");
}

static void testHarmonyPresets(const File& root){
    auto file=root.getChildFile("harmony-preset-core.json");file.deleteFile();std::vector<HarmonyPreset> rows;
    expect(loadHarmonyPresets(file,rows).wasOk()&&rows.empty()&&harmonyPresetToken(file)=="missing","missing harmony library starts empty");bool valid=true,roundtrip=true;int factories=0;for(auto kind:{HarmonyPresetKind::fitScale,HarmonyPresetKind::chord})for(const auto& p:factoryHarmonyPresets(kind)){++factories;valid&=validateHarmonyPreset(p).wasOk();HarmonyPreset loaded;roundtrip&=harmonyPresetFromJson(harmonyPresetToJson(p),loaded).wasOk()&&JSON::toString(harmonyPresetToJson(p),false,22)==JSON::toString(harmonyPresetToJson(loaded),false,22);}expect(valid&&factories==13,"all thirteen factory harmony presets build valid settings");expect(roundtrip,"scale and chord factory settings roundtrip exactly");
    auto p=factoryHarmonyPresets(HarmonyPresetKind::chord)[4];p.id="personal-dorian";p.name=String::fromUTF8("Мой аккорд");p.chord.length=2.125;p.chord.velocity=.617f;p.chord.skipExact=false;p.chord.beat=37;expect(putHarmonyPreset(file,p,false,"missing").wasOk(),"save Unicode-named harmony settings with a bounded token");expect(loadHarmonyPresets(file,rows).wasOk()&&rows.size()==1&&rows[0].name==p.name&&rows[0].chord.beat==0&&rows[0].chord.length==2.125&&rows[0].chord.velocity==.617f&&!rows[0].chord.skipExact,"reload preserves musical settings while insertion beat stays outside the file");auto json=harmonyPresetToJson(p);expect(!json["settings"].hasProperty("beat")&&!json.hasProperty("notes"),"harmony preset contains settings only and no target beat or notes");std::vector<Note> a,b;auto original=p.chord;original.beat=3;auto recalled=rows[0].chord;recalled.beat=3;expect(buildChord({},8,p.guide,original,a).wasOk()&&buildChord({},8,rows[0].guide,recalled,b).wasOk()&&a==b,"disk-reloaded chord produces the same notes at a new insertion point");
    auto minimum=p;minimum.chord.velocity=.01f;HarmonyPreset minimumRead;expect(harmonyPresetFromJson(harmonyPresetToJson(minimum),minimumRead).wasOk()&&minimumRead.chord.velocity==.01f,"minimum one-percent chord velocity roundtrips without float-boundary rejection");
    auto token=harmonyPresetToken(file),bytes=file.loadFileAsString();expect(putHarmonyPreset(file,p,false,token).failed()&&file.loadFileAsString()==bytes,"duplicate identity cannot silently overwrite a personal harmony preset");auto duplicate=p;duplicate.id="another";duplicate.name=p.name.toUpperCase();expect(putHarmonyPreset(file,duplicate,false,token).failed()&&file.loadFileAsString()==bytes,"same-tool names are unique without case differences");duplicate.kind=HarmonyPresetKind::fitScale;duplicate.direction=ScaleDirection::up;expect(putHarmonyPreset(file,duplicate,false,token).wasOk(),"separate harmony tools can use the same name");expect(putHarmonyPreset(file,p,true,token).failed()&&removeHarmonyPreset(file,p.id,token).failed(),"stale library tokens block update and delete");p.name="Dorian voicing";expect(putHarmonyPreset(file,p,true,harmonyPresetToken(file)).wasOk()&&loadHarmonyPresets(file,rows).wasOk()&&rows.size()==2&&rows[0].name==p.name,"explicit rename/update retains one identity");auto wrong=p;wrong.kind=HarmonyPresetKind::fitScale;expect(putHarmonyPreset(file,wrong,true,harmonyPresetToken(file)).failed(),"update cannot switch a preset to another harmony tool");
    auto exchange=root.getChildFile("one-harmony.pulseharmony");exchange.deleteFile();expect(saveHarmonyPresets(exchange,{p}).wasOk()&&loadHarmonyPresets(exchange,rows).wasOk()&&rows.size()==1&&rows[0].guide==p.guide,"single-file harmony exchange preserves tonic scale and chord settings");auto sentinel=duplicate;auto sentinelJson=JSON::toString(harmonyPresetToJson(sentinel));for(auto key:{"root","quality","inversion","octaves","length","velocity","skipExact"}){auto bad=harmonyPresetToJson(p);bad["settings"].getDynamicObject()->removeProperty(key);expect(harmonyPresetFromJson(bad,sentinel).failed()&&JSON::toString(harmonyPresetToJson(sentinel))==sentinelJson,"missing chord fields reject without altering the destination");}for(auto value:{var(true),var("60"),var(60.5),var(-1),var(128)}){auto bad=harmonyPresetToJson(p);bad["settings"].getDynamicObject()->setProperty("root",value);expect(harmonyPresetFromJson(bad,sentinel).failed(),"chord root rejects noninteger nonnumeric and out-of-range values");}
    auto bad=p;bad.chord.root=127;expect(validateHarmonyPreset(bad).failed(),"out-of-range generated chord tones reject structurally");bad=p;bad.guide.scale=9;expect(validateHarmonyPreset(bad).failed(),"diatonic seventh preset requires a seven-note scale");bad=p;bad.chord.length=std::nan("");expect(validateHarmonyPreset(bad).failed(),"nonfinite preset duration rejects");bad=p;bad.name=" unsafe ";expect(validateHarmonyPreset(bad).failed(),"untrimmed names reject");
    bytes=file.loadFileAsString();file.replaceWithText("{broken");rows={p};expect(loadHarmonyPresets(file,rows).failed()&&rows.size()==1&&rows[0].id==p.id,"corrupt harmony library does not clear valid in-memory rows");expect(putHarmonyPreset(file,p,true).failed()&&removeHarmonyPreset(file,p.id).failed()&&file.loadFileAsString()=="{broken","corrupt library blocks mutations and retains original bytes");file.replaceWithText(bytes);expect(removeHarmonyPreset(file,p.id,harmonyPresetToken(file)).wasOk()&&loadHarmonyPresets(file,rows).wasOk()&&rows.size()==1&&rows[0].id==duplicate.id,"delete removes one preset and retains other tool entries");
    std::vector<HarmonyPreset> full;for(int i=0;i<maxHarmonyPresets;++i){auto row=duplicate;row.id="id-"+String(i);row.name="Preset "+String(i);full.push_back(row);}expect(saveHarmonyPresets(file,full).wasOk()&&putHarmonyPreset(file,p,false).failed(),"harmony library capacity is bounded without dropping existing presets");auto stale=harmonyPresetToken(exchange);exchange.replaceWithText("changed externally");expect(saveHarmonyPresets(exchange,{p},stale).failed()&&exchange.loadFileAsString()=="changed externally","exchange save checks destination token before overwriting");exchange.replaceWithText(String::repeatedString(" ",262145));expect(loadHarmonyPresets(exchange,rows).failed()&&harmonyPresetToken(exchange)=="unavailable","oversized harmony files reject before parsing");
    testProgressionPresets(root);
}
